import{_ as a,c as e,o,aj as n}from"./chunks/framework.B-K7myP5.js";const h=JSON.parse('{"title":"json 完全解析","frontmatter":{"title":"json 完全解析","createTime":"2025/01/17 19:27:31","permalink":"/docs/composer/schema.html","lastUpdated":"2026-01-22","tags":[],"link":"/docs/composer/教程/schema","layout":"doc","sidebar":true,"aside":true,"prev":{"text":"Composer 命令的使用","link":"/docs/composer/教程/cli"},"next":{"text":"扩展包源仓库","link":"/docs/composer/教程/repositories"}},"headers":[],"params":{"pkg":"composer/教程/schema","sidebar":[{"text":"常见问题","items":[{"text":"如何为我的框架自定义一个扩展包安装目录？","link":"/docs/composer/index"},{"text":"如何使用脚本安装 Composer？","link":"/docs/composer/常见问题/to-install-composer-programmatically"},{"text":"使用 root 用户来安装扩展包是否安全？如何安全地安装未认证渠道的扩展包？","link":"/docs/composer/常见问题/to-install-untrusted-packages-safely"},{"text":"我应该将 vendor 目录加入版本控制吗？","link":"/docs/composer/常见问题/i-commit-the-dependencies-in-my-vendor-directory"},{"text":"Composer 使用的是什么版本命名规范？","link":"/docs/composer/常见问题/version-numbering-system-does-composer-itself-use"},{"text":"为什么限制版本是最佳实践？","link":"/docs/composer/常见问题/are-unbound-version-constraints-a-bad-idea"},{"text":"为何版本限制与对比符、通配符配合使用是个糟糕的行为？","link":"/docs/composer/常见问题/are-version-constraints-combining-comparisons-and-wildcards-a-bad-idea"},{"text":"为什么 Composer 不递归加载代码库？","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively"}]},{"text":"官方文章","items":[{"text":"分支别名","link":"/docs/composer/官方文章/aliases"},{"text":"版本限制","link":"/docs/composer/官方文章/versions"},{"text":"自动加载器优化","link":"/docs/composer/官方文章/optimization"},{"text":"自定义安装器","link":"/docs/composer/官方文章/installers"},{"text":"使用 Satis 处理私有仓库","link":"/docs/composer/官方文章/private-packages-with-satis"},{"text":"HTTP 基础认证","link":"/docs/composer/官方文章/basic-authentication"},{"text":"创建 Composer 插件","link":"/docs/composer/官方文章/plugins"},{"text":"事件和自定义脚本","link":"/docs/composer/官方文章/scripts"},{"text":"故障排除","link":"/docs/composer/官方文章/troubleshooting"},{"text":"可执行二进制文件","link":"/docs/composer/官方文章/binaries"}]},{"text":"教程","items":[{"text":"简介","link":"/docs/composer/教程/intro"},{"text":"基本使用","link":"/docs/composer/教程/basic-usage"},{"text":"创建扩展包","link":"/docs/composer/教程/libraries"},{"text":"Composer 命令的使用","link":"/docs/composer/教程/cli"},{"text":"json 完全解析","link":"/docs/composer/教程/schema"},{"text":"扩展包源仓库","link":"/docs/composer/教程/repositories"},{"text":"配置信息","link":"/docs/composer/教程/config"},{"text":"社区","link":"/docs/composer/教程/community"}]}],"versions":[]},"relativePath":"docs/composer/教程/schema.md","filePath":"docs/[pkg].md"}'),p={name:"docs/composer/教程/schema.md"};function t(i,s,l,c,r,d){return o(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="composer-json-组织架构" tabindex="-1">composer.json 组织架构 <a class="header-anchor" href="#composer-json-组织架构" aria-label="Permalink to “composer.json 组织架构”">​</a></h1><p>这个章节将会讲解 <code>composer.json</code> 中所有字段。</p><h2 id="json-格式" tabindex="-1">JSON 格式 <a class="header-anchor" href="#json-格式" aria-label="Permalink to “JSON 格式”">​</a></h2><p>使用  <a href="http://json-schema.org/" target="_blank" rel="noreferrer">JSON schema</a> 模式来记录和验证格式，你也可以在 <a href="https://getcomposer.org/schema.json" target="_blank" rel="noreferrer">https://getcomposer.org/schema.json</a> 中来参照。</p><h2 id="根项目" tabindex="-1">根项目 <a class="header-anchor" href="#根项目" aria-label="Permalink to “根项目”">​</a></h2><p>根项目是由当前项目目录下的 <code>composer.json</code> 定义的项目，<code>composer.json</code> 中定义了您当前项目的依赖项。</p><p>某些字段仅在根项目中的上下文中应用，举个例子， <code>config</code> 字段，只有根项目才能定义和配置，依赖项的配置将会被忽略，这代表 <code>config</code> 字段是 <code>root-only</code></p><blockquote><p>注意：当前项目可以是根项目，也可以不是，具体取决于你的上下文环境，例如，如果您的项目依赖于 <code>monolog</code> 库，那么您的项目就是根节点。但是，如果您从 GitHub 中克隆 <code>monolog</code> 库来修复它的 bug，那么 <code>monolog</code> 库就是根项目。 属性</p></blockquote><hr><h3 id="name-名称" tabindex="-1"><code>name</code> 名称 <a class="header-anchor" href="#name-名称" aria-label="Permalink to “name 名称”">​</a></h3><p>包的名称，由作者名称和项目名称组成，使用 <code>/</code> 分割，例如：</p><ul><li>monolog/monolog</li><li>igorw/event-source</li></ul><p>包名称可以包含任何字符，包括空格，并且不区分大小写 ( <code>foo/bar</code> 和 <code>Foo/Bar</code> 会被认为是同一个包)。为了简化安装，建议定义一个不包含非字母数字字符或空格的短名称。</p><p>发布一个包（库）的必要条件</p><h3 id="description-描述" tabindex="-1"><code>description</code> 描述 <a class="header-anchor" href="#description-描述" aria-label="Permalink to “description 描述”">​</a></h3><p>包的简短描述，通常这是一行介绍就行。</p><p>发布一个包（库）的必要条件</p><h3 id="version-版本" tabindex="-1"><code>version</code> 版本 <a class="header-anchor" href="#version-版本" aria-label="Permalink to “version 版本”">​</a></h3><p>包的版本，在大多数情况下，这不是必须的，应该省略（参考下文）。</p><p>必须遵循  <code>X.Y.Z</code> 或 <code>vX.Y.Z</code>，可选后缀 <code>-dev</code>, <code>-patch</code> ( <code>-p</code> ), <code>-alpha</code> ( <code>-a</code> ), <code>-beta</code> ( <code>-b</code> ) 或 <code>-RC</code>， <code>patch </code>, <code>alpha</code> , <code>beta</code> 和 <code>RC</code> 后缀也可以跟一个数字。</p><p>例如:</p><ul><li>1.0.0</li><li>1.0.2</li><li>1.1.0</li><li>0.2.5</li><li>1.0.0-dev</li><li>1.0.0-alpha3</li><li>1.0.0-beta2</li><li>1.0.0-RC5</li><li>v2.0.4-p1</li></ul><p>如果包仓库可以从某个位置推断出版本，则可填，例如 VCS 仓库中的 VCS 标记名称，这种情况还是建议省略掉。</p><blockquote><p>注意: 包列表使用 VCS 存储，因此上面的语句对于包列表也是有效。由于人为错误，您自己指定版本很有可能最终会在某些时候出现问题（建议搜索学习：语义化版本）。</p></blockquote><h3 id="type-类型" tabindex="-1"><code>type</code> 类型 <a class="header-anchor" href="#type-类型" aria-label="Permalink to “type 类型”">​</a></h3><p>包的类型，默认为库 <code>library</code> 。</p><p>包类型用于自定义安装逻辑。如果您有一个包需要一个特殊逻辑，您可以定义一个自定义类型。 这可以是 <code>symfony-bundle</code>， <code>wordpress-plugin</code> 或者 <code>typo3-module</code>。这些类型都将用于某些特定的项目。而对应的项目将要提供一种能够安装该类型包的安装程序。</p><p><code>Composer</code> 原生支持以下4种类型：</p><ul><li>library: 默认类型，它只需要将文件复制到 <code>vendor</code> 目录。</li><li>project: 当前包是一个项目，而不是一个库。例：框架应用程序 <a href="https://github.com/symfony/symfony-standard" target="_blank" rel="noreferrer">Symfony standard edition</a>，内容管理系统  <a href="https://github.com/silverstripe/silverstripe-installer" target="_blank" rel="noreferrer">SilverStripe installer</a> 或者完全成熟的分布式应用程序。使用 IDE 创建一个新的工作区时，这可以为其提供项目列表的初始化。</li><li>metapackage: 包含需求并将触发其安装的空包，但不包含文件，并且不会向系统写入任何内容。因此这种安装类型并不需要一个 dist 或 source。</li><li>composer-plugin: 一个安装类型为 <code>composer-plugin</code> 的包，它有一个自定义安装类型，可以为其它包提供一个 <code>installler</code>。详细请查看<a href="https://github.com/composer/composer/blob/master/doc/articles/custom-installers.md" target="_blank" rel="noreferrer">自定义安装类型</a>。</li></ul><p>只有在安装过程中需要自定义逻辑时才使用自定义类型。建议省略该字段并将其默认为库 <code>library</code>。</p><h3 id="keywords" tabindex="-1"><code>keywords</code> <a class="header-anchor" href="#keywords" aria-label="Permalink to “keywords”">​</a></h3><p>一组用于搜索与筛选的与包相关的关键字。</p><p>例如：</p><ul><li>logging</li><li>events</li><li>database</li><li>redis</li><li>templating</li></ul><p>非必须。</p><h3 id="homepage" tabindex="-1"><code>homepage</code> <a class="header-anchor" href="#homepage" aria-label="Permalink to “homepage”">​</a></h3><p>项目网站的 URL 地址。</p><p>非必须。</p><h3 id="readme" tabindex="-1"><code>readme</code> <a class="header-anchor" href="#readme" aria-label="Permalink to “readme”">​</a></h3><p>README 文档的绝对路径。</p><p>非必须。</p><h3 id="time" tabindex="-1"><code>time</code> <a class="header-anchor" href="#time" aria-label="Permalink to “time”">​</a></h3><p>版本发布日期。</p><p>必须是 <code>YYYY-MM-DD</code> 或者 <code>YYYY-MM-DD HH:MM:SS</code> 格式。</p><p>非必须。</p><h3 id="license" tabindex="-1"><code>license</code> <a class="header-anchor" href="#license" aria-label="Permalink to “license”">​</a></h3><p>包的许可证。可以是一个字符串或者是一个字符串数组。</p><p>最常见的许可证推荐表示法如下（按字母排序）：</p><ul><li>Apache-2.0</li><li>BSD-2-Clause</li><li>BSD-3-Clause</li><li>BSD-4-Clause</li><li>GPL-2.0-only / GPL-2.0-or-later</li><li>GPL-3.0-only / GPL-3.0-or-later</li><li>LGPL-2.1-only / LGPL-2.1-or-later</li><li>LGPL-3.0-only / LGPL-3.0-or-later</li><li>MIT</li></ul><p>虽然是一个可选项，但是非常建议提供此项信息。更多的标识符列在了 <a href="https://spdx.org/licenses/" target="_blank" rel="noreferrer">SPDX Open Source License Registry</a>。</p><p>对于闭源软件，你可能需要使用 <code>&quot;proprietary&quot;</code> 作为许可标识符。</p><p>示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;license&quot;: &quot;MIT&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>对于一个包来说，当在多个许可证之间进行选择时（『析取许可证』），可以将多个许可指定为一个数组。</p><p>一个析取许可证的示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;license&quot;: [</span></span>
<span class="line"><span>       &quot;LGPL-2.1-only&quot;,</span></span>
<span class="line"><span>       &quot;GPL-3.0-or-later&quot;</span></span>
<span class="line"><span>    ]</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>也可以在括号内用 &quot;or&quot; 将它们分开。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;license&quot;: &quot;(LGPL-2.1-only or GPL-3.0-or-later)&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>同理，当需要使用多个许可证时（『合取许可证』），它们应该在括号内使用 &quot;and&quot; 分隔。</p><h3 id="authors" tabindex="-1"><code>authors</code> <a class="header-anchor" href="#authors" aria-label="Permalink to “authors”">​</a></h3><p>包的作者。这是一个对象数组。</p><p>每一个作者对象可以包含以下属性：</p><ul><li>name: 作者的名字。通常是真实姓名。</li><li>email: 作者的邮件地址。</li><li>homepage: 作者个人网站的 URL 地址。</li><li>role: 作者在项目中担任的角色（如：开发者或者译者）。</li></ul><p>示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;authors&quot;: [</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;name&quot;: &quot;Nils Adermann&quot;,</span></span>
<span class="line"><span>            &quot;email&quot;: &quot;naderman@naderman.de&quot;,</span></span>
<span class="line"><span>            &quot;homepage&quot;: &quot;http://www.naderman.de&quot;,</span></span>
<span class="line"><span>            &quot;role&quot;: &quot;Developer&quot;</span></span>
<span class="line"><span>        },</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;name&quot;: &quot;Jordi Boggiano&quot;,</span></span>
<span class="line"><span>            &quot;email&quot;: &quot;j.boggiano@seld.be&quot;,</span></span>
<span class="line"><span>            &quot;homepage&quot;: &quot;https://seld.be&quot;,</span></span>
<span class="line"><span>            &quot;role&quot;: &quot;Developer&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    ]</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>虽然是可选项，但是强烈建议写上。</p><h3 id="support" tabindex="-1"><code>support</code> <a class="header-anchor" href="#support" aria-label="Permalink to “support”">​</a></h3><p>获取对项目支持的信息对象。</p><p>对象信息必须包括以下属性：</p><ul><li>email: 项目支持 email 地址。</li><li>issues: 跟踪问题的 URL 地址。</li><li>forum: 论坛 URL 地址。</li><li>wiki:  Wiki URL 地址。</li><li>irc: IRC 聊天频道地址，as irc://server/channel.</li><li>source: 网址浏览或下载源。</li><li>docs: 文件的 URL 。</li><li>rss: RSS 源的 URL 。</li></ul><p>一个实例:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;support&quot;: {</span></span>
<span class="line"><span>        &quot;email&quot;: &quot;support@example.org&quot;,</span></span>
<span class="line"><span>        &quot;irc&quot;: &quot;irc://irc.freenode.org/composer&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>可选。</p><h3 id="包链接" tabindex="-1">包链接 <a class="header-anchor" href="#包链接" aria-label="Permalink to “包链接”">​</a></h3><p>所有这些都使用一个对象，该对象通过版本限制将包名称映射到包的版本。在<a href="https://github.com/composer/composer/blob/master/doc/articles/versions.md" target="_blank" rel="noreferrer">这里</a>阅读更多关于版本的信息。</p><p>实例:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;require&quot;: {</span></span>
<span class="line"><span>        &quot;monolog/monolog&quot;: &quot;1.0.*&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>所有的这些都是可选的。</p><p><code>require</code> 和 <code>require-dev</code> 还支持稳定性标签 (<a href="https://github.com/composer/composer/blob/master/doc/04-schema.md#root-package" target="_blank" rel="noreferrer">root-only</a>)。 这允许你在 <a href="https://github.com/composer/composer/blob/master/doc/04-schema.md#minimum-stability" target="_blank" rel="noreferrer">minimum-stability</a> 设定的范围外做进一步的限制或扩展。 您可以将它们应用于版本约束，或者将它们应用到空版本约束，例如，如果允许不稳定的依赖性包。</p><p>实例:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;require&quot;: {</span></span>
<span class="line"><span>        &quot;monolog/monolog&quot;: &quot;1.0.*@beta&quot;,</span></span>
<span class="line"><span>        &quot;acme/foo&quot;: &quot;@dev&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>如果一个依赖有对另一个不稳定包的依赖， 你最好在 <code>require</code> 中显示的定义它，并带上详细的稳定性标识。</p><p>实例:</p><p>如果 <code>doctrine/doctrine-fixtures-bundle</code> 需要 <code>&quot;doctrine/data-fixtures&quot;: &quot;dev-master&quot;</code>然后在根 Composer.json 中你需要添加下面的第二行，以允许 <code>dev</code> 发布 <code>doctrine/data-fixtures</code> 包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;require&quot;: {</span></span>
<span class="line"><span>        &quot;doctrine/doctrine-fixtures-bundle&quot;: &quot;dev-master&quot;,</span></span>
<span class="line"><span>        &quot;doctrine/data-fixtures&quot;: &quot;@dev&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>require</code> 和 <code>require-dev</code> 还支持对 dev（开发）版本的明确引用（即：版本控制中的提交编号 commit），以确保它们被锁定到一个给定的状态，即使你运行了更新命令。你只需要明确一个开发版本号，并带上诸如 <code>#&lt;ref&gt;</code> 的标识。这也是一个 <a href="https://github.com/composer/composer/blob/master/doc/04-schema.md#root-package" target="_blank" rel="noreferrer">root-only</a> 特性，将在依赖关系中被忽略。 例如:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;require&quot;: {</span></span>
<span class="line"><span>        &quot;monolog/monolog&quot;: &quot;dev-master#2eb0c0978d290a1c45346a1955188929cb4e5db7&quot;,</span></span>
<span class="line"><span>        &quot;acme/foo&quot;: &quot;1.0.x-dev#abc123&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><blockquote><p>请注意：这个特性有严重的技术限制，即 composer.json 的元数据仍将被从你在哈希前面指定的分支中读取。因此，此功能应该被用于开发期间临时修复问题时使用，然后之后你就可以切换至打过 tag 过的发行版本。Composer 团队对此功能不提供活跃的支持，也不接受由此产生的 BUG 报告。</p></blockquote><p>您也可以使用 “版本行内别名”（inline-alias）包约束，用以满足其它情况下满足不了的限定。了解更多信息 <a href="https://github.com/composer/composer/blob/master/doc/articles/aliases.md" target="_blank" rel="noreferrer">查阅别名相关文章</a>。</p><p><code>require</code> 和 <code>require-dev</code> 同时也支持指定你项目成功运行所需要的 PHP 版本和 PHP 扩展。</p><p>例如:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;require&quot; : {</span></span>
<span class="line"><span>        &quot;php&quot; : &quot;^5.5 || ^7.0&quot;,</span></span>
<span class="line"><span>        &quot;ext-mbstring&quot;: &quot;*&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><blockquote><p>请注意：项目中列举出 PHP 扩展其实是挺重要的。并非所有的 PHP 安装后的环境都是相同的：有些可能缺失了部分扩展而你却认为是标准化安装的（例如 <code>ext-mysqli</code> 在 Fedora/CentOS 精简化安装中就不会被默认安装的）。一例失败的 PHP 扩展依赖列举会带来糟糕的使用体验：Composer 安装你包的时候不报错，但运行时却失败。这个 <code>composer show --platform</code> 命令可用于列出你系统中可用的 PHP 扩展，可用来帮助你列举你用到的和所需的扩展。除此之外，你也可以使用第三方的工具来分析你项目用到的扩展的清单。</p></blockquote><h4 id="require" tabindex="-1">require <a class="header-anchor" href="#require" aria-label="Permalink to “require”">​</a></h4><p>必须安装的依赖包列表，这些包必须满足条件，否则不会安装。</p><h4 id="require-dev-root-only" tabindex="-1">require-dev (<a href="https://github.com/composer/composer/blob/master/doc/04-schema.md#root-package" target="_blank" rel="noreferrer">root-only</a>) <a class="header-anchor" href="#require-dev-root-only" aria-label="Permalink to “require-dev (root-only)”">​</a></h4><p>开发或运行测试时的依赖包列表。根目录下的 <code>composer.json</code> 即 root 包，root 包需要的 <code>dev</code> 依赖默认安装， 安装和更新都支持 —no-dev 选项，以避免 <code>dev</code> 依赖被安装。</p><h4 id="conflict" tabindex="-1">conflict <a class="header-anchor" href="#conflict" aria-label="Permalink to “conflict”">​</a></h4><p>列表中的包与当前包冲突，不允许同时安装。</p><blockquote><p>请注意，在 <code>conflict</code> 中,比如指定 <code>&lt;1.0 &gt;=1.1</code> 的版本范围时，表示小于 <code>1.0</code> 且大于或等于 <code>1.1</code> 的版本冲突，这种约束写法是错误的，应为 <code>&lt;1.0 | &gt;= 1.1</code> 。</p></blockquote><h4 id="replace" tabindex="-1">replace <a class="header-anchor" href="#replace" aria-label="Permalink to “replace”">​</a></h4><p>列表中的包将被当前包替换。所以你可以 fork 一个包，以不同的名称、版本号发布。之后如果有其他任何包依赖原包，将依赖于你 fork 的包。</p><p>这对于一个内部包含子包的主包很有用。例如 <code>symfony/symfony</code> 这个主包，包含了 <code>Symfony</code> 的所有组件，而这些组件又可以单独的发布。如果你 require 了主包，那么它就会自动完成其下各个子包的依赖，因为主包取代了子包。</p><blockquote><p>请注意，在上述方法取代子包时，你应该只对子包使用 <code>self.version</code> 这一个版本约束，以确保主包仅替换子包的准确版本，而不是其他版本。</p></blockquote><h4 id="provider" tabindex="-1">provider <a class="header-anchor" href="#provider" aria-label="Permalink to “provider”">​</a></h4><p>此程序包提供了一个其他程序包列表。 这对于通用接口非常有用， 一个包可能依赖于一些虚拟的<code>logger</code>包，任何实现这个logger接口的库都可以在<code>provide</code>中列出来。</p><h4 id="suggest" tabindex="-1">suggest <a class="header-anchor" href="#suggest" aria-label="Permalink to “suggest”">​</a></h4><p>建议的包可以增强或者适用于当前的包，这些信息，在这个包安装完成之后显示，以便给用户提供可供安装的更多包的信息，即使他们不是被严格要求的。</p><p>格式如同上面包的链接，除了值是纯文本，且不包含版本信息。</p><p>例子如下:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;suggest&quot;: {</span></span>
<span class="line"><span>        &quot;monolog/monolog&quot;: &quot;Allows more advanced logging of the application flow&quot;,</span></span>
<span class="line"><span>        &quot;ext-xml&quot;: &quot;Needed to support XML format in class Foo&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="autoload" tabindex="-1">autoload <a class="header-anchor" href="#autoload" aria-label="Permalink to “autoload”">​</a></h3><p>PHP 自动加载的映射。</p><p>支持 <a href="http://www.php-fig.org/psr/psr-4/" target="_blank" rel="noreferrer"><code>PSR-4</code></a> 和 <a href="http://www.php-fig.org/psr/psr-0/" target="_blank" rel="noreferrer"><code>PSR-0</code></a> 自动加载，<code>class</code> 映射 和 <code>files</code> 引用。</p><p>推荐使用 <code>PSR-4</code> 规范（添加类时，无需重新生成自动加载映射）。</p><h4 id="psr-4" tabindex="-1">PSR-4 <a class="header-anchor" href="#psr-4" aria-label="Permalink to “PSR-4”">​</a></h4><p>使用 <code>PSR-4</code> 时，你可以定义从命名空间到路径的映射。 例如，当加载 <code>Foo\\\\Bar\\\\Baz</code> 这样的类，且在 <code>composer.json</code> 定义命名空间前缀 <code>Foo\\\\</code> 指向目录 <code>src/</code> 时 ，自动加载器将查找 <code>src/Bar/Baz.php</code> 且命名空间前缀为 <code>Foo\\\\</code> 的文件并包含它（如果存在）。</p><blockquote><p>请注意，与旧的 <code>PSR-0</code> 不同的是，<code>PSR-4</code> 的文件路径中不存在与前缀 <code>Foo\\\\</code> 对应的 <code>Foo/</code> 目录。</p></blockquote><p>命名空间前缀必须以 <code>\\\\</code> 结尾，以避免类似前缀间的冲突。例如，前缀 <code>Foo</code> 可能匹配 <code>ForBar</code> 命名空间的类，因此尾部的反斜杠解决了这种问题。 在安装、更新时，PSR-4的引用都被生成单个 <code>key=&gt;value</code> 的数组，该数组可以在生成文件 <code>vendor/composer/autoload_psr4.php</code> 中查看。</p><p>例:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;autoload&quot;: {</span></span>
<span class="line"><span>        &quot;psr-4&quot;: {</span></span>
<span class="line"><span>            &quot;Monolog\\\\&quot;: &quot;src/&quot;,</span></span>
<span class="line"><span>            &quot;Vendor\\\\Namespace\\\\&quot;: &quot;&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>如果需要在多个目录中加载相同前缀，可以指定为数组。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;autoload&quot;: {</span></span>
<span class="line"><span>        &quot;psr-4&quot;: { &quot;Monolog\\\\&quot;: [&quot;src/&quot;, &quot;lib/&quot;] }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>如果需要加载目录中所有命名空间的类，可以使用一个空前缀，如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;autoload&quot;: {</span></span>
<span class="line"><span>        &quot;psr-4&quot;: { &quot;&quot;: &quot;src/&quot; }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="psr-0" tabindex="-1">PSR-0 <a class="header-anchor" href="#psr-0" aria-label="Permalink to “PSR-0”">​</a></h4><p>使用 <code>PSR-0</code> 时，可以定义相对于包的根目录，命名空间到路径的映射。也支持 <code>PEAR-style</code> 的非命名空间约定。</p><blockquote><p>请注意，<code>PSR-0</code> 的命名空间前缀也必须以 <code>\\\\</code> 结尾，以避免类似前缀间的冲突。</p></blockquote><p>在安装、更新时，<code>PSR-0</code> 的引用都被生成单个 <code>key=&gt;value</code> 的数组，该数组可以在生成文件 <code>vendor/composer/autoload_namespaces.php</code> 中查看。</p><p>例:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;autoload&quot;: {</span></span>
<span class="line"><span>        &quot;psr-0&quot;: {</span></span>
<span class="line"><span>            &quot;Monolog\\\\&quot;: &quot;src/&quot;,</span></span>
<span class="line"><span>            &quot;Vendor\\\\Namespace\\\\&quot;: &quot;src/&quot;,</span></span>
<span class="line"><span>            &quot;Vendor_Namespace_&quot;: &quot;src/&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>如果需要在多个目录中加载相同前缀，可以指定为数组：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;autoload&quot;: {</span></span>
<span class="line"><span>        &quot;psr-0&quot;: { &quot;Monolog\\\\&quot;: [&quot;src/&quot;, &quot;lib/&quot;] }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>PSR-0</code> 不仅可以用于命名空间的声明，还可以直接指定到类。这对于在全局命名空间中只有一个类的包非常有用。例如，只有一个 <code>php</code> 文件位于包的根目录中，则可能声明为：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;autoload&quot;: {</span></span>
<span class="line"><span>        &quot;psr-0&quot;: { &quot;UniqueGlobalClass&quot;: &quot;&quot; }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>如果需要加载目录中所有命名空间的类，可以使用一个空前缀，如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;autoload&quot;: {</span></span>
<span class="line"><span>        &quot;psr-0&quot;: { &quot;&quot;: &quot;src/&quot; }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="classmap" tabindex="-1">Classmap <a class="header-anchor" href="#classmap" aria-label="Permalink to “Classmap”">​</a></h4><p>在安装或更新的时候，<code>classmap</code> 被组合成单个键值对数组（key=&gt;value）的形式，这个数组可以在 <code>vendor/composer/autoload_classmap.php</code> 中找到。这个映射是通过扫描给定的 文件夹/文件中所有的<code>.php</code>和<code>.inc</code>来生成的。</p><p>您可以通过生成类映射来自动加载不遵循PSR-0/4的库。通过设定要搜索类的所有目录或文件来进行配置。</p><p>Example:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;autoload&quot;: {</span></span>
<span class="line"><span>        &quot;classmap&quot;: [&quot;src/&quot;, &quot;lib/&quot;, &quot;Something.php&quot;]</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to “Files”">​</a></h4><p>如果你想在每个请求中引入某个文件，那么你可以使用 <code>files</code> 自动加载机制。这有利于加载包中无法自动加载的php函数。</p><p>Example:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;autoload&quot;: {</span></span>
<span class="line"><span>        &quot;files&quot;: [&quot;src/MyLibrary/functions.php&quot;]</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="exclude-files-from-classmaps" tabindex="-1">Exclude files from classmaps <a class="header-anchor" href="#exclude-files-from-classmaps" aria-label="Permalink to “Exclude files from classmaps”">​</a></h4><p>我们可以使用 <code>exclude-from-classmap</code> 从类库映射中排查某些文件或文件夹。这很方便我们在生成环境中排查测试类，例如，在构建加载的时候自动加载器会排除这些类。</p><p>类映射生成器将忽略此处配置的路径中的所有文件。这些路径是包根目录（即composer.json位置）的绝对路径，并且支持<code>*</code>来匹配除斜杠之外的任何东西，并且<code>**</code>来匹配任何东西。 <code>**</code>隐含地添加到路径的末尾。</p><p>Example:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;autoload&quot;: {</span></span>
<span class="line"><span>        &quot;exclude-from-classmap&quot;: [&quot;/Tests/&quot;, &quot;/test/&quot;, &quot;/tests/&quot;]</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="优化自动加载" tabindex="-1">优化自动加载 <a class="header-anchor" href="#优化自动加载" aria-label="Permalink to “优化自动加载”">​</a></h4><p>自动加载会对请求时间产生较大的影响（类较多的大型框架中每个请求自动加载器将会耗时 50-100 ms）。点击查看如何 <a href="https://github.com/composer/composer/blob/master/doc/articles/autoloader-optimization.md" target="_blank" rel="noreferrer">优化自动加载</a>。</p><h3 id="autoload-dev-root-only" tabindex="-1">autoload-dev (<a href="https://github.com/composer/composer/blob/master/doc/04-schema.md#root-package" target="_blank" rel="noreferrer">root-only</a>) <a class="header-anchor" href="#autoload-dev-root-only" aria-label="Permalink to “autoload-dev (root-only)”">​</a></h3><p>这个节点允许允许为开发阶段自定义加载规则。 运行测试套件所需的类不应包含在主自动加载规则中，以避免在生产中污染自动加载器以及其他人将您的包用作依赖项。 因此，最好使用专用路径进行单元测试，并将其添加到 autoload-dev 部分。</p><p>例如:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;autoload&quot;: {</span></span>
<span class="line"><span>        &quot;psr-4&quot;: { &quot;MyLibrary\\\\&quot;: &quot;src/&quot; }</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    &quot;autoload-dev&quot;: {</span></span>
<span class="line"><span>        &quot;psr-4&quot;: { &quot;MyLibrary\\\\Tests\\\\&quot;: &quot;tests/&quot; }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="include-path" tabindex="-1">include-path <a class="header-anchor" href="#include-path" aria-label="Permalink to “include-path”">​</a></h3><blockquote><p>弃用: 这里仅仅用于支持遗留项目，所有的新代码最好使用自动加载。因此，这是一种弃用的做法，但该功能本身不会从 Composer 中消失。</p></blockquote><p>应该附加到PHP的 <code>include_path</code> 的路径列表。</p><p>例如:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;include-path&quot;: [&quot;lib/&quot;]</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这是可选的。</p><h3 id="target-dir" tabindex="-1">target-dir <a class="header-anchor" href="#target-dir" aria-label="Permalink to “target-dir”">​</a></h3><blockquote><p>弃用：这仅用于支持传统的 PSR-0 样式自动加载，并且所有新代码最好是没有使用 target-dir 的 PSR-4，鼓励使用 PHP 命名空间的 PSR-0 项目转移到PSR-4。</p></blockquote><p>定义安装目标。</p><p>如果包的根路径位于命名空间声明之下，则无法正确自动加载。 <code>target-dir</code> 解决了这个问题。</p><p>例如 Symfony，组件都是单独的包。 Yaml 组件位于 <code>Symfony\\Component\\Yaml</code> 下。包的根路径是 <code>Yaml</code> 目录。如果要自动加载，我们需要确保它没有安装到 <code>vendor/symfony/ yaml</code> 中，而是安装到 <code>vendor/symfony/yaml/Symfony/Component/Yaml</code> 中，以便自动加载器可以从 <code>vendor/symfony/yaml</code> 中加载。 为此，<code>autoload</code> 和 <code>target-dir</code> 定义如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;autoload&quot;: {</span></span>
<span class="line"><span>        &quot;psr-0&quot;: { &quot;Symfony\\\\Component\\\\Yaml\\\\&quot;: &quot;&quot; }</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    &quot;target-dir&quot;: &quot;Symfony/Component/Yaml&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这是可选的。</p><h3 id="minimum-stability-root-only" tabindex="-1">minimum-stability (<a href="https://github.com/composer/composer/blob/master/doc/04-schema.md#root-package" target="_blank" rel="noreferrer">root-only</a>) <a class="header-anchor" href="#minimum-stability-root-only" aria-label="Permalink to “minimum-stability (root-only)”">​</a></h3><p>这定义了按稳定性过滤包的默认值，默认为<code>stable</code>。所以如果你依赖<code>dev</code> 包，你应该在你的文件中指定。</p><p>所有包都将根据稳定性检出相应的版本，那些低于 <code>minimum-stability</code> 设置的版本将被自动忽略。（请注意，你还可以使用在 <code>require</code> 中指定的版本约束来定义每个包的稳定性要求（请参阅<a href="https://github.com/composer/composer/blob/master/doc/04-schema.md#package-links" target="_blank" rel="noreferrer">package links</a>）。</p><p>可用选项（按稳定性排序）是 <code>dev</code>，<code>alpha</code>，<code>beta</code>，<code>RC</code> 和 <code>stable</code>。</p><h3 id="prefer-stable-root-only" tabindex="-1">prefer-stable (<a href="https://github.com/composer/composer/blob/master/doc/04-schema.md#root-package" target="_blank" rel="noreferrer">root-only</a>) <a class="header-anchor" href="#prefer-stable-root-only" aria-label="Permalink to “prefer-stable (root-only)”">​</a></h3><p>启用此项后，如果可以找到兼容的稳定包，Composer 将优先选择比不稳定包更稳定的包。如果您需要开发版本或者某个软件包只有alpha可用，那么仍然会选择那些允许最小稳定性允许的包。</p><p>使用 <code>&quot;prefer-stable&quot;: true</code> 来开启此项.</p><h3 id="repositories-root-only" tabindex="-1">repositories (<a href="https://github.com/composer/composer/blob/master/doc/04-schema.md#root-package" target="_blank" rel="noreferrer">root-only</a>) <a class="header-anchor" href="#repositories-root-only" aria-label="Permalink to “repositories (root-only)”">​</a></h3><p>使用自定义的安装源。</p><p>Composer 默认只使用 packagist 的安装源。通过定义 repositories 你可以从任何其他地方获取包。</p><p>存储库不会递归解析，您只能将它们添加到主 <code>composer.json</code> 中。依赖项中 <code>composer.json</code> 的 repositories 配置被忽略。</p><p>支持以下安装源类型:</p><ul><li>composer: Composer 存储库只是通过网络（HTTP，FTP，SSH）提供的 <code>packages.json</code> 文件，其中包含带有额外 <code>dist</code> 或 <code>source</code> 信息的 <code>composer.json</code> 对象列表。 <code>packages.json</code> 文件使用PHP流加载。您可以使用 <code>options</code> 参数在该流上设置额外选项。</li><li>vcs: 版本控制系统存储库可以从git, svn, fossil 或 hg repositories。</li><li>pear: 通过 pear，可以将任何 pear 存储库导入 Composer 项目。</li><li>package:  如果依赖于一个不支持 composer 的项目，可以使用 <code>package</code> 来定义包。只需要内联 <code>composer.json</code> 对象。</li></ul><p>更多信息，请参阅 <a href="/docs/composer/2018/05-repositories/2086">Repositories</a>.</p><p>例如:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;repositories&quot;: [</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;type&quot;: &quot;composer&quot;,</span></span>
<span class="line"><span>            &quot;url&quot;: &quot;http://packages.example.com&quot;</span></span>
<span class="line"><span>        },</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;type&quot;: &quot;composer&quot;,</span></span>
<span class="line"><span>            &quot;url&quot;: &quot;https://packages.example.com&quot;,</span></span>
<span class="line"><span>            &quot;options&quot;: {</span></span>
<span class="line"><span>                &quot;ssl&quot;: {</span></span>
<span class="line"><span>                    &quot;verify_peer&quot;: &quot;true&quot;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        },</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;type&quot;: &quot;vcs&quot;,</span></span>
<span class="line"><span>            &quot;url&quot;: &quot;https://github.com/Seldaek/monolog&quot;</span></span>
<span class="line"><span>        },</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;type&quot;: &quot;pear&quot;,</span></span>
<span class="line"><span>            &quot;url&quot;: &quot;https://pear2.php.net&quot;</span></span>
<span class="line"><span>        },</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            &quot;type&quot;: &quot;package&quot;,</span></span>
<span class="line"><span>            &quot;package&quot;: {</span></span>
<span class="line"><span>                &quot;name&quot;: &quot;smarty/smarty&quot;,</span></span>
<span class="line"><span>                &quot;version&quot;: &quot;3.1.7&quot;,</span></span>
<span class="line"><span>                &quot;dist&quot;: {</span></span>
<span class="line"><span>                    &quot;url&quot;: &quot;https://www.smarty.net/files/Smarty-3.1.7.zip&quot;,</span></span>
<span class="line"><span>                    &quot;type&quot;: &quot;zip&quot;</span></span>
<span class="line"><span>                },</span></span>
<span class="line"><span>                &quot;source&quot;: {</span></span>
<span class="line"><span>                    &quot;url&quot;: &quot;https://smarty-php.googlecode.com/svn/&quot;,</span></span>
<span class="line"><span>                    &quot;type&quot;: &quot;svn&quot;,</span></span>
<span class="line"><span>                    &quot;reference&quot;: &quot;tags/Smarty_3_1_7/distribution/&quot;</span></span>
<span class="line"><span>                }</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    ]</span></span>
<span class="line"><span>}</span></span></code></pre></div><blockquote><p>注意：顺序在这里很重要。在查找包时，Composer 将从第一个存储库查找到最后一个存储库，然后选择第一个匹配项。默认情况下，最后添加 Packagist ，这意味着自定义存储库可以覆盖它的包。 也可以使用JSON对象表示法。但是 JSON 的 key/value 是无序的，因此无法保证一致的行为。</p></blockquote><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>   &quot;repositories&quot;: {</span></span>
<span class="line"><span>        &quot;foo&quot;: {</span></span>
<span class="line"><span>            &quot;type&quot;: &quot;composer&quot;,</span></span>
<span class="line"><span>            &quot;url&quot;: &quot;http://packages.foo.com&quot;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="config-root-only" tabindex="-1">config (<a href="https://github.com/composer/composer/blob/master/doc/04-schema.md#root-package" target="_blank" rel="noreferrer">root-only</a>) <a class="header-anchor" href="#config-root-only" aria-label="Permalink to “config (root-only)”">​</a></h3><p>一组配置选项。它仅用于项目。详情请参阅 <a href="https://github.com/composer/composer/blob/master/doc/06-config.md" target="_blank" rel="noreferrer">Config</a> 。</p><h3 id="scripts-root-only" tabindex="-1">scripts (<a href="https://github.com/composer/composer/blob/master/doc/04-schema.md#root-package" target="_blank" rel="noreferrer">root-only</a>) <a class="header-anchor" href="#scripts-root-only" aria-label="Permalink to “scripts (root-only)”">​</a></h3><p>Composer 允许再安装过程的各个部分中执行脚本。</p><p>详情请参阅 <a href="https://github.com/composer/composer/blob/master/doc/articles/scripts.md" target="_blank" rel="noreferrer">Scripts</a> 。</p><h3 id="extra" tabindex="-1">extra <a class="header-anchor" href="#extra" aria-label="Permalink to “extra”">​</a></h3><p><code>scripts</code> 使用的任意扩展数据。</p><p>这几乎可以是任意的东西，要从脚本事件处理程序中访问它，您可以执行以下操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$extra = $event-&gt;getComposer()-&gt;getPackage()-&gt;getExtra();</span></span></code></pre></div><p>这是可选的。</p><h3 id="bin" tabindex="-1">bin <a class="header-anchor" href="#bin" aria-label="Permalink to “bin”">​</a></h3><p>一组被链接到 <code>bin-dir</code> 的二进制文件（来自config）。</p><p>详情请参阅 <a href="https://github.com/composer/composer/blob/master/doc/articles/vendor-binaries.md" target="_blank" rel="noreferrer">Vendor Binaries</a> 。</p><p>这是可选的。</p><h3 id="archive" tabindex="-1">archive <a class="header-anchor" href="#archive" aria-label="Permalink to “archive”">​</a></h3><p>一组用于创建包归档的选项。</p><p>支持以下选项：</p><ul><li>exclude:允许配置一组需要排除的路径，语法与 <code>.gitignore</code> 文件一致。如果开头使用（!）将代表包含任意匹配文件，即使它们之前被排除了。<code>/</code> 表示从项目相对路径的根目录进行匹配，<code>*</code> 不会扩展到目录分隔符。</li></ul><p>例如:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;archive&quot;: {</span></span>
<span class="line"><span>        &quot;exclude&quot;: [&quot;/foo/bar&quot;, &quot;baz&quot;, &quot;/*.test&quot;, &quot;!/foo/bar/baz&quot;]</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这个例子将会包含 <code>/dir/foo/bar/file</code>, <code>/foo/bar/baz</code>, <code>/file.php</code>, <code>/foo/my.test</code> 并且排除 <code>/foo/bar/any</code>, <code>/foo/baz</code>, 和 <code>/my.test</code>.</p><p>这是可选的。</p><h3 id="abandoned-弃用" tabindex="-1">abandoned（弃用） <a class="header-anchor" href="#abandoned-弃用" aria-label="Permalink to “abandoned（弃用）”">​</a></h3><p>标记此包是否已经被弃用</p><p>它可以是布尔值也可以指向推荐替代的包名称或 URL。</p><p>例如:</p><p>使用 <code>&quot;abandoned&quot;: true</code> 来定义这个包已经被弃用了。 使用 <code>&quot;abandoned&quot;: &quot;monolog/monolog&quot;</code>来定义这个包已经被弃用，并且它的替代包是 <code>monolog/monolog</code>。</p><p>默认为 false。</p><p>这是可选的。</p><h3 id="non-feature-branches-非功能分支" tabindex="-1">non-feature-branches（非功能分支） <a class="header-anchor" href="#non-feature-branches-非功能分支" aria-label="Permalink to “non-feature-branches（非功能分支）”">​</a></h3><p>一组非数字（例如 “latest” 或其他类似的标记）命名的分支的正则表达式列表，不会作为功能分支处理。这是一个字符串数组。</p><p>如果您有非数字分支名称，例如 &quot;latest&quot;, &quot;current&quot;, &quot;latest-stable&quot; 或其它类似的命名，它们看起来不像版本号，那么 Composer 会将此类分支作为功能分支处理。它会搜索父分支，直到搜索到版本或在特殊分支（如 master）结束，包的根版本号成为父分支的版本或至少是master或者其他类似的命名。</p><p>要将非数字命名分支作为版本处理，而不是搜索具有有效版本或特殊分支名称（如 master ）的父分支，可以设置分支名称的模式，这些模式应作为 dev 版本分支处理。</p><p>这将有利于依赖使用 “self.version” 的包，因此不是dev-master，而是安装了相同的分支（例如：latest-testing）。</p><p>例如: 如果你有一个测试分支，在测试阶段大量维护并部署到你的临时环境，通常 <code>composer show -s</code> 会给你 <code>versions : * dev-master</code>。 如果你将  <code>latest-.*</code>  配置为非功能分支的模式，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;non-feature-branches&quot;: [&quot;latest-.*&quot;]</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>那么 <code>composer show -s</code>将会给你 <code>versions : * dev-latest-testing</code>.</p><p>这是可选的。</p>`,226)])])}const g=a(p,[["render",t]]);export{h as __pageData,g as default};
